DB_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tailoring_orders.db')

def get_db():
    conn = sqlite3.connect(DB_FILE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    cursor = conn.cursor()
    
    # Custom Stitching Orders Table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_number TEXT UNIQUE NOT NULL,
            customer_name TEXT NOT NULL,
            phone TEXT NOT NULL,
            whatsapp TEXT,
            email TEXT,
            address TEXT,
            dress_type TEXT NOT NULL,
            lining_type TEXT,
            neck_style TEXT,
            sleeve_style TEXT,
            measurement_type TEXT NOT NULL,
            measurements_json TEXT,
            fabric_status TEXT NOT NULL,
            special_instructions TEXT,
            urgency TEXT DEFAULT 'Normal (3-5 Days)',
            estimated_price REAL DEFAULT 0.0,
            advance_paid REAL DEFAULT 0.0,
            delivery_date TEXT,
            status TEXT DEFAULT 'Order Received',
            master_notes TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # Inquiries Table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS inquiries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT NOT NULL,
            message TEXT NOT NULL,
            status TEXT DEFAULT 'New',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    conn.commit()

    cursor.execute('SELECT COUNT(*) FROM orders')
    if cursor.fetchone()[0] == 0:
        seed_sample_orders(conn)
        
    conn.close()

