@app.route('/api/orders', methods=['GET'])
def api_get_orders():
    """Fetch orders with search and status filter"""
    status_filter = request.args.get('status', '').strip()
    search = request.args.get('search', '').strip()

    conn = get_db()
    cursor = conn.cursor()

    query = 'SELECT * FROM orders WHERE 1=1'
    params = []

    if status_filter:
        query += ' AND status = ?'
        params.append(status_filter)

    if search:
        query += ' AND (order_number LIKE ? OR customer_name LIKE ? OR phone LIKE ? OR dress_type LIKE ?)'
        wildcard = f'%{search}%'
        params.extend([wildcard, wildcard, wildcard, wildcard])

    query += ' ORDER BY id DESC'
    cursor.execute(query, params)
    rows = cursor.fetchall()
    orders = [dict(row) for row in rows]
    conn.close()

    return jsonify(orders)

@app.route('/api/orders', methods=['POST'])
def api_create_order():
    """Create a new custom stitching order"""
    data = request.get_json() or {}

    if not data.get('customer_name') or not data.get('phone') or not data.get('dress_type'):
        return jsonify({'success': False, 'error': 'Name, Phone, and Dress Type are required.'}), 400

    conn = get_db()
    cursor = conn.cursor()

    # Generate sequential unique Order ID for Ambattur shop
    cursor.execute('SELECT MAX(id) FROM orders')
    max_id = cursor.fetchone()[0] or 1000
    next_num = max_id + 1
    order_number = f"AMB-{datetime.now().year}-{next_num}"

    cursor.execute('''
        INSERT INTO orders (
            order_number, customer_name, phone, whatsapp, email, address,
            dress_type, lining_type, neck_style, sleeve_style,
            measurement_type, measurements_json, fabric_status,
            special_instructions, urgency, estimated_price, advance_paid,
            delivery_date, status, master_notes
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ''', (
        order_number,
        data.get('customer_name'),
        data.get('phone'),
        data.get('whatsapp', data.get('phone')),
        data.get('email', ''),
        data.get('address', 'Ambattur, Chennai'),
        data.get('dress_type'),
        data.get('lining_type', 'Standard Pure Cotton'),
        data.get('neck_style', 'Round Neck'),
        data.get('sleeve_style', 'Elbow Length'),
        data.get('measurement_type', 'custom_measurements'),
        data.get('measurements_json', '{}'),
        data.get('fabric_status', 'Dropped at Ambattur shop'),
        data.get('special_instructions', ''),
        data.get('urgency', 'Normal (3-5 Days)'),
        float(data.get('estimated_price', 0.0)),
        float(data.get('advance_paid', 0.0)),
        data.get('delivery_date', ''),
        data.get('status', 'Order Received'),
        data.get('master_notes', 'New online request logged.')
    ))

    conn.commit()
    conn.close()

    return jsonify({'success': True, 'order_number': order_number, 'id': cursor.lastrowid})

@app.route('/api/orders/<int:order_id>', methods=['GET'])
def api_get_order_details(order_id):
    """Retrieve detailed order information for Master Tailor Job Sheet"""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM orders WHERE id = ?', (order_id,))
    row = cursor.fetchone()
    conn.close()

    if not row:
        return jsonify({'error': 'Order not found'}), 404

    return jsonify(dict(row))

@app.route('/api/orders/<int:order_id>', methods=['PATCH'])
def api_update_order(order_id):
    """Update order status, advance payments, and tailor workshop notes"""
    data = request.get_json() or {}
    conn = get_db()
    cursor = conn.cursor()

    updates = []
    params = []

    if 'status' in data:
        updates.append('status = ?')
        params.append(data['status'])

    if 'advance_paid' in data:
        updates.append('advance_paid = ?')
        params.append(float(data['advance_paid']))

    if 'master_notes' in data:
        updates.append('master_notes = ?')
        params.append(data['master_notes'])

    if 'delivery_date' in data:
        updates.append('delivery_date = ?')
        params.append(data['delivery_date'])

    if not updates:
        return jsonify({'success': False, 'error': 'No fields provided'}), 400

    params.append(order_id)
    query = f"UPDATE orders SET {', '.join(updates)} WHERE id = ?"
    cursor.execute(query, params)
    conn.commit()
    conn.close()

    return jsonify({'success': True})

@app.route('/api/orders/<int:order_id>', methods=['DELETE'])
def api_delete_order(order_id):
    """Delete / Cancel order"""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('DELETE FROM orders WHERE id = ?', (order_id,))
    conn.commit()
    conn.close()
    return jsonify({'success': True})

@app.route('/api/track', methods=['GET'])
def api_track():
    """Customer-facing order tracker by Order ID or Phone number"""
    query_str = request.args.get('q', '').strip()
    if not query_str:
        return jsonify({'found': False})

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        SELECT order_number, customer_name, dress_type, status, delivery_date, estimated_price, advance_paid, master_notes
        FROM orders
        WHERE order_number = ? OR phone = ? OR whatsapp = ?
        ORDER BY id DESC LIMIT 1
    ''', (query_str, query_str, query_str))

    row = cursor.fetchone()
    conn.close()

    if row:
        return jsonify({'found': True, 'order': dict(row)})
    return jsonify({'found': False})

@app.route('/api/stats', methods=['GET'])
def api_stats():
    """KPI summary stats for shop administration"""
    conn = get_db()
    cursor = conn.cursor()

    cursor.execute('SELECT COUNT(*) FROM orders')
    total = cursor.fetchone()[0]

    cursor.execute('SELECT COUNT(*) FROM orders WHERE status = "Order Received"')
    received = cursor.fetchone()[0]

    cursor.execute('SELECT COUNT(*) FROM orders WHERE status IN ("Cutting & Stitching", "Fabric Received")')
    stitching = cursor.fetchone()[0]

    cursor.execute('SELECT COUNT(*) FROM orders WHERE status = "Ready for Pickup"')
    ready = cursor.fetchone()[0]

    cursor.execute('SELECT SUM(estimated_price) FROM orders WHERE status != "Cancelled"')
    revenue = cursor.fetchone()[0] or 0.0

    conn.close()

    return jsonify({
        'total': total,
        'received': received,
        'stitching': stitching,
        'ready': ready,
        'total_revenue': revenue
    })

@app.route('/api/inquiry', methods=['POST'])
def api_inquiry():
    """Save customer contact inquiry"""
    data = request.get_json() or {}
    name = data.get('name')
    phone = data.get('phone')
    message = data.get('message')

    if not name or not phone or not message:
        return jsonify({'success': False, 'error': 'Missing fields'}), 400

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('INSERT INTO inquiries (name, phone, message) VALUES (?, ?, ?)', (name, phone, message))
    conn.commit()
    conn.close()

    return jsonify({'success': True})

@app.route('/api/export/csv', methods=['GET'])
def api_export_csv():
    """Export orders to a downloadable CSV spreadsheet"""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT order_number, customer_name, phone, dress_type, estimated_price, advance_paid, status, delivery_date, created_at FROM orders ORDER BY id DESC')
    rows = cursor.fetchall()
    conn.close()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(['Order ID', 'Customer Name', 'Phone', 'Dress Type', 'Est. Price', 'Advance', 'Status', 'Delivery Date', 'Created At'])
    for r in rows:
        writer.writerow(list(r))

    output.seek(0)
    return Response(
        output.getvalue(),
        mimetype="text/csv",
        headers={"Content-Disposition": "attachment;filename=Ambattur_Tailoring_Orders.csv"}
    )

